stockGuardScript:
(function () {
  const SOLD_OUT_IMAGES = new Set([
    "compressed_1795517033781.webp",
    "compressed_1795517029070.webp",
    "compressed_1795517024344.webp"
  ]);

  function ensureThumbSoldOutStyles() {
    if (document.getElementById("caramel-thumb-soldout-style")) return;
    const style = document.createElement("style");
    style.id = "caramel-thumb-soldout-style";
    style.textContent = 
      .caramel-thumb-soldout-img {
        filter: grayscale(85%) brightness(0.35) contrast(0.95) !important;
      }

      /* تغميق أي أيقونة داخل حاوية الصورة المصغرة عند نفاد الكمية */
      .caramel-soldout-wrap svg,
      .caramel-soldout-wrap i,
      .caramel-soldout-wrap [class*="icon"],
      .caramel-soldout-wrap img:not(.caramel-thumb-soldout-badge) {
        filter: grayscale(85%) brightness(0.35) !important;
        opacity: 0.55 !important;
      }

      .caramel-thumb-soldout-badge {
        position: absolute !important;
        top: 50% !important;
        left: 50% !important;
        transform: translate(-50%, -50%) !important;
        z-index: 99 !important;
        background: rgba(155, 14, 14, 0.96) !important;
        color: #ffffff !important;
        padding: 3px 7px !important;
        border-radius: 6px !important;
        font-weight: 800 !important;
        font-size: 9.5px !important;
        line-height: 1.2 !important;
        text-align: center !important;
        white-space: nowrap !important;
        box-shadow: 0 3px 10px rgba(0, 0, 0, 0.75) !important;
        border: 1px solid rgba(255, 255, 255, 0.45) !important;
        pointer-events: none !important;
        filter: none !important;
        opacity: 1 !important;
      }
    ;
    document.head.appendChild(style);
  }

  function extractFileName(pathOrUrl = "") {
    if (!pathOrUrl) return "";
    const clean = String(pathOrUrl).split("?")[0].split("#")[0];
    const parts = clean.split("/");
    return (parts[parts.length - 1] || "").toLowerCase();
  }

  function isImageOutOfStock(pathOrUrl = "") {
    return SOLD_OUT_IMAGES.has(extractFileName(pathOrUrl));
  }

  function normalizeProductStock(product) {
    const images = Array.isArray(product.images)
      ? product.images
      : product.img
      ? [product.img]
      : [];

    const soldOutImages = images.filter((img) => isImageOutOfStock(img));
    const mainImgSoldOut = isImageOutOfStock(product.img);
    const allImagesSoldOut = images.length > 0 && soldOutImages.length === images.length;
    const stockNum = typeof product.stock === "number" ? product.stock : undefined;

    const outOfStock =
      Boolean(product.outOfStock) ||
      mainImgSoldOut ||
      allImagesSoldOut ||
      (stockNum !== undefined && stockNum <= 0);

    return {
      ...product,
      stock: outOfStock ? 0 : stockNum ?? 1,
      outOfStock,
      soldOutImages
    };
  }

  function detectActiveImage(product, modalOrCardRoot = null) {
    const scope =
      modalOrCardRoot ||
      document.querySelector(".product-modal.open, .modal.show, .modal.active, [data-product-modal].open") ||
      document;

    const candidates = [
      scope.querySelector(".main-img img, .product-main-img, .modal-img img, [data-active-image]"),
      scope.querySelector(".gallery-main img, .swiper-slide-active img, .carousel-item.active img"),
      scope.querySelector("img")
    ].filter(Boolean);

    for (const el of candidates) {
      const src = el.currentSrc || el.getAttribute("src") || el.dataset.src || "";
      if (src) return src;
    }

    const activeThumb = scope.querySelector(".thumb.active img, .thumbnail.active img, .thumbs img.active");
    if (activeThumb) {
      return activeThumb.currentSrc || activeThumb.getAttribute("src") || "";
    }

    return product && product.img ? product.img : "";
  }

  function inferSelectionFromActiveImage(product, activeImageSrc = "", currentSelection = null) {
    const fileName = extractFileName(activeImageSrc);
    const images = Array.isArray(product.images) ? product.images : [];
    const imgIndex = images.findIndex((im) => extractFileName(im) === fileName);

    const matchedSize =
      Array.isArray(product.sizes) && imgIndex >= 0 && product.sizes[imgIndex]
        ? product.sizes[imgIndex]
        : null;

    const matchedVariant =
      Array.isArray(product.variants) && imgIndex >= 0 && product.variants[imgIndex]
        ? product.variants[imgIndex]
        : null;

    const autoLabel =
      (matchedSize && (matchedSize.label || matchedSize.name)) ||
      (matchedVariant && (matchedVariant.label || matchedVariant.name)) ||
      (fileName ? الموديل المعروض (${fileName}) : "");

    const resolvedSelection =
      currentSelection ||
      matchedSize ||
      matchedVariant ||
      (autoLabel ? { label: autoLabel, name: autoLabel, img: activeImageSrc, price: product.price } : null);

    return {
      activeImageSrc,
      autoLabel,
      selection: resolvedSelection,
      isActiveImageSoldOut: isImageOutOfStock(activeImageSrc)
    };
  }

  function buildCartItemFromActiveView(product, options = {}) {
    const norm = normalizeProductStock(product);
    const qty = Math.max(1, Number(options.qty || 1));
    const activeImageSrc = options.activeImageSrc || detectActiveImage(norm, options.root);
    const inferred = inferSelectionFromActiveImage(norm, activeImageSrc, options.selectedOption || null);

    const chosenLabel =
      (options.selectedOption && (options.selectedOption.label || options.selectedOption.name)) ||
      inferred.autoLabel ||
      "الموديل المعروض";

    const chosenPrice =
      (options.selectedOption && Number(options.selectedOption.price)) ||
      (inferred.selection && Number(inferred.selection.price)) ||
      Number(norm.price || 0);

    return {
      ...norm,
      qty,
      quantity: qty,
      price: chosenPrice,
      img: activeImageSrc || norm.img,
      selectedOption: chosenLabel,
      selectedLabel: chosenLabel,
      autoSelectedFromImage: !options.selectedOption
    };
  }

  function canAddToCart(product, selectedVariantOrSize = null, qty = 1, options = {}) {
    const norm = normalizeProductStock(product);
    const activeImageSrc = options.activeImageSrc || detectActiveImage(norm, options.root);
    const inferred = inferSelectionFromActiveImage(norm, activeImageSrc, selectedVariantOrSize);

    if (inferred.isActiveImageSoldOut) {
      return {
        allowed: false,
        reason: عذراً، الموديل الظاهر في الصورة نفذت كميته حالياً.
      };
    }

    if (inferred.selection && inferred.selection.outOfStock) {
      return {
        allowed: false,
        reason: عذراً، الخيار "${inferred.selection.label || inferred.selection.name}" نفذت كميته حالياً.
      };
    }

    const hasOtherAvailableOptions =
      Array.isArray(norm.sizes) && norm.sizes.length > 0
        ? norm.sizes.some((s) => !s.outOfStock)
        : !norm.outOfStock;

    if ((norm.outOfStock || norm.stock <= 0) && !hasOtherAvailableOptions) {
      return {
        allowed: false,
        reason: عذراً، المنتج "${norm.title}" نفذت كميته حالياً.
      };
    }

    if (qty > Math.max(norm.stock, 1)) {
      return {
        allowed: false,
        reason: الكمية المتاحة من "${norm.title}" هي ${norm.stock} فقط.
      };
    }

    return { allowed: true, reason: "" };
  }

  function addActiveViewToCart(product, addFn, options = {}) {
    const qty = Math.max(1, Number(options.qty || 1));
    const activeImageSrc = options.activeImageSrc || detectActiveImage(product, options.root);
    const inferred = inferSelectionFromActiveImage(product, activeImageSrc, options.selectedOption || null);
    const check = canAddToCart(product, inferred.selection, qty, {
      ...options,
      activeImageSrc
    });

    if (!check.allowed) {
      if (typeof options.onBlocked === "function") {
        options.onBlocked(check.reason);
      } else if (typeof window.alert === "function") {
        window.alert(check.reason);
      }
      return { added: false, reason: check.reason, item: null };
    }

    const itemToAdd = buildCartItemFromActiveView(product, {
      ...options,
      activeImageSrc,
      selectedOption: inferred.selection,
      qty
    });

    if (typeof addFn === "function") {
      addFn(itemToAdd);
    }

    return { added: true, reason: "", item: itemToAdd };
  }

  function sortProductsSoldOutLast(list = []) {
    return [...list].map(normalizeProductStock).sort((a, b) => {
      if (a.outOfStock === b.outOfStock) return 0;
      return a.outOfStock ? 1 : -1;
    });
  }

  function renderSoldOutBadge(product, options = {}) {
    ensureThumbSoldOutStyles();
    const norm = normalizeProductStock(product);
    const activeSrc = options.activeImageSrc || norm.img || "";
    const isActiveImgSold = isImageOutOfStock(activeSrc);

    if (options.thumb) {
      if (!isActiveImgSold && !norm.outOfStock) return "";
      return <span class="caramel-thumb-soldout-badge" data-soldout="true">نفذت الكمية</span>;
    }

    return "";
  }

  function isThumbnailImage(img) {
    const rect = img.getBoundingClientRect();
    const w = rect.width || img.offsetWidth || Number(img.getAttribute("width")) || 0;
    const h = rect.height || img.offsetHeight || Number(img.getAttribute("height")) || 0;

    const inThumbContainer = Boolean(
      img.closest(
        ".thumbs, .thumbnails, .thumb-list, .gallery-thumbs, .swiper-thumbs, [class*='thumb'], [class*='preview-list'], [class*='mini']"
      )
    );

    if (inThumbContainer) return true;
    if (w > 0 && h > 0 && w <= 125 && h <= 125) return true;
    return false;
  }

  function applyThumbSoldOutToDOM(root = document) {
    ensureThumbSoldOutStyles();
    const imgs = root.querySelectorAll("img");
    imgs.forEach((img) => {
      if (img.classList.contains("caramel-thumb-soldout-badge")) return;
      const src = img.currentSrc || img.getAttribute("src") || img.dataset.src || "";
      if (!isImageOutOfStock(src)) return;
      if (!isThumbnailImage(img)) return;

      const parent = img.parentElement;
      if (!parent) return;

      const computedPos = window.getComputedStyle(parent).position;
      if (computedPos === "static") {
        parent.style.position = "relative";
      }

      parent.classList.add("caramel-soldout-wrap");
      img.classList.add("caramel-thumb-soldout-img");

      if (!parent.querySelector(":scope > [data-caramel-thumb-soldout='1']")) {
        const badge = document.createElement("span");
        badge.className = "caramel-thumb-soldout-badge";
        badge.setAttribute("data-caramel-thumb-soldout", "1");
        badge.textContent = "نفذت الكمية";
        parent.appendChild(badge);
      }
    });
  }

  if (typeof window !== "undefined") {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", () => applyThumbSoldOutToDOM());
    } else {
      applyThumbSoldOutToDOM();
    }
    const observer = new MutationObserver(() => applyThumbSoldOutToDOM());
    if (document.documentElement) {
      observer.observe(document.documentElement, { childList: true, subtree: true });
    }
  }

  window.CaramelStockGuard = {
    ensureThumbSoldOutStyles,
    isImageOutOfStock,
    normalizeProductStock,
    detectActiveImage,
    inferSelectionFromActiveImage,
    buildCartItemFromActiveView,
    canAddToCart,
    addActiveViewToCart,
    sortProductsSoldOutLast,
    renderSoldOutBadge,
    applyThumbSoldOutToDOM
  };
})();
